local VENDOR_PAT="^([^\t]*)\t([^\t]*)\t([^\t]*)\t([^\t]*)\t([^\t]*)\t([^\t]*)\t([^\t]*)$"
function S.Material(id) return S.items[id]~=nil end
function S.Label(id)
 local row=S.items[id];if not row then return "Source unknown" end
 local flags=row[1];local parts={}
 if flags%2==1 then parts[#parts+1]="Merchant supply" end
 if math.floor(flags/4)%2==1 then parts[#parts+1]=(S.worldKinds and S.worldKinds[id]) or "World objects" end
 if math.floor(flags/2)%2==1 then parts[#parts+1]="Creature drop" end
 return #parts>0 and table.concat(parts," / ") or "Source unknown"
end
function S.Vendor(id)
 if cache[id] then return cache[id] end
 local at=S.vendorOffsets[id];if not at then return end
 local last=S.vendorText:find("\n",at,true) or (#S.vendorText+1)
 local line=S.vendorText:sub(at,last-1)
 local _,f2,f3,f4,f5,f6,f7=line:match(VENDOR_PAT)
 if not f2 then return end
 local row={id=id,name=f2,zone=f3,map=tonumber(f4),x=tonumber(f5),y=tonumber(f6),faction=f7}
 local old=cacheRing[cacheCursor];if old then cache[old]=nil end
 cacheRing[cacheCursor]=id;cacheCursor=cacheCursor%CACHE_CAP+1
 cache[id]=row;return row
end

